[data-workspace-area="conversation"]{background-image:var(--sx-actor),var(--sx-actor-2),radial-gradient(120% 55% at 50% -12%,color-mix(in srgb,var(--sx-accent) var(--sx-ambient),transparent),transparent 62%)!important;background-size:520px 240px,360px 130px,100% 100%!important;background-position:right 3% top 3%,0 100%,0 0!important;background-repeat:no-repeat,repeat-x,no-repeat!important}
[data-workspace-area="conversation"]::after{background:radial-gradient(70% 55% at 50% 0%,color-mix(in srgb,var(--sx-accent) 10%,transparent),transparent 72%);opacity:0}
:root:has(.chat-markdown[data-streaming],.live-tool-shine) [data-workspace-area="conversation"]::after{opacity:1}
[data-slot="sidebar-inner"]{background-image:var(--sx-actor-2),var(--sx-side-glow),var(--surface-grain,none)!important;background-size:360px 130px,100% 100%,var(--surface-grain-size,auto)!important;background-position:0 100%,0 0,0 0!important;background-repeat:repeat-x,no-repeat,repeat!important}
@media (prefers-reduced-motion:reduce){[data-workspace-area="conversation"]::before,[data-workspace-area="conversation"]::after,[data-slot="sidebar-inner"]::before{animation:none!important;transition:none!important}h1:has([data-draft-project-trigger])::before{content:none}[data-workspace-area="conversation"],[data-slot="sidebar-inner"]{--sx-actor:none;--sx-actor-2:none;--sx-pc:transparent}}
